#!/bin/sh
# Generated by grader_matrix: same artifacts, same tools, every run.
echo '[CPG_LABEL] benign.cubin BENIGN'
echo '[CPG_LABEL] poc_sec08_shsize_00000000ffffffff.cubin MALICIOUS'
echo '[CPG_LABEL] poc_sec08_shsize_fffffffffffffff0.cubin MALICIOUS'
echo '[CPG_LABEL] ctrl_sec08_shsize_restored_0000000000000010.cubin CONTROL'
for artifact in benign.cubin poc_sec08_shsize_00000000ffffffff.cubin poc_sec08_shsize_fffffffffffffff0.cubin ctrl_sec08_shsize_restored_0000000000000010.cubin; do
  [ -f "$artifact" ] || continue
  base=$(basename "$artifact")
  nvdisasm "$artifact" > /dev/null 2>&1
  echo "[CPG_RUN] $base::nvdisasm exit=$?"
  cuobjdump --dump-elf "$artifact" > /dev/null 2>&1
  echo "[CPG_RUN] $base::cuobjdump exit=$?"
done
true
